using Store;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _cart;

    public ShoppingCartTests()
    {
        _cart = new ShoppingCart();
    }

    // ──────────────────────────────────────────────
    //  AddItem
    // ──────────────────────────────────────────────

    [TestMethod]
    public void AddItem_SingleItem_AppearsInCart()
    {
        _cart.AddItem("SKU-001", 2, 9.99m);

        Assert.HasCount(1, _cart.Items);
        Assert.AreEqual((2, 9.99m), _cart.Items["SKU-001"]);
    }

    [TestMethod]
    public void AddItem_DuplicateSku_CombinesQuantity()
    {
        _cart.AddItem("SKU-001", 1, 5.00m);
        _cart.AddItem("SKU-001", 3, 5.00m);

        Assert.HasCount(1, _cart.Items);
        Assert.AreEqual(4, _cart.Items["SKU-001"].Quantity);
    }

    [TestMethod]
    public void AddItem_MultipleDistinctSkus_AllAppear()
    {
        _cart.AddItem("A", 1, 1.00m);
        _cart.AddItem("B", 2, 2.00m);
        _cart.AddItem("C", 3, 3.00m);

        Assert.HasCount(3, _cart.Items);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void AddItem_NullOrWhiteSpaceSku_Throws(string? sku)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.AddItem(sku!, 1, 1.00m));
    }

    [TestMethod]
    public void AddItem_ZeroQuantity_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _cart.AddItem("SKU-001", 0, 1.00m));
    }

    [TestMethod]
    public void AddItem_NegativeQuantity_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _cart.AddItem("SKU-001", -1, 1.00m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _cart.AddItem("SKU-001", 1, -5.00m));
    }

    [TestMethod]
    public void AddItem_ZeroPrice_DoesNotThrow()
    {
        _cart.AddItem("FREE-ITEM", 1, 0.00m);

        Assert.AreEqual(0.00m, _cart.Items["FREE-ITEM"].Price);
    }

    // ──────────────────────────────────────────────
    //  RemoveItem
    // ──────────────────────────────────────────────

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        _cart.AddItem("SKU-001", 1, 5.00m);

        _cart.RemoveItem("SKU-001");

        Assert.IsEmpty(_cart.Items);
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ThrowsKeyNotFound()
    {
        Assert.ThrowsExactly<KeyNotFoundException>(
            () => _cart.RemoveItem("MISSING"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void RemoveItem_NullOrWhiteSpaceSku_Throws(string? sku)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.RemoveItem(sku!));
    }

    [TestMethod]
    public void RemoveItem_OnlyRemovesTargetItem()
    {
        _cart.AddItem("A", 1, 1.00m);
        _cart.AddItem("B", 1, 2.00m);

        _cart.RemoveItem("A");

        Assert.HasCount(1, _cart.Items);
        Assert.Contains("B", _cart.Items.Keys);
    }

    // ──────────────────────────────────────────────
    //  CalculateTotal
    // ──────────────────────────────────────────────

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_SingleItem_ReturnsCorrectTotal()
    {
        _cart.AddItem("SKU-001", 3, 10.00m);

        Assert.AreEqual(30.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_SumsAll()
    {
        _cart.AddItem("A", 2, 5.00m);   // 10.00
        _cart.AddItem("B", 1, 15.00m);  // 15.00

        Assert.AreEqual(25.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_AfterRemovingItem_ExcludesRemoved()
    {
        _cart.AddItem("A", 1, 10.00m);
        _cart.AddItem("B", 1, 20.00m);
        _cart.RemoveItem("A");

        Assert.AreEqual(20.00m, _cart.CalculateTotal());
    }

    // ──────────────────────────────────────────────
    //  ApplyCoupon
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow("SAVE10", 90.00)]
    [DataRow("SAVE20", 80.00)]
    [DataRow("HALF", 50.00)]
    public void ApplyCoupon_ValidCode_ReducesTotal(string code, double expectedTotal)
    {
        _cart.AddItem("SKU-001", 1, 100.00m);

        _cart.ApplyCoupon(code);

        Assert.AreEqual((decimal)expectedTotal, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCode_ThrowsArgumentException()
    {
        var ex = Assert.ThrowsExactly<ArgumentException>(
            () => _cart.ApplyCoupon("BOGUS"));

        Assert.Contains("BOGUS", ex.Message);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void ApplyCoupon_NullOrWhiteSpaceCode_Throws(string? code)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.ApplyCoupon(code!));
    }

    [TestMethod]
    public void ApplyCoupon_ReplacedBySecondCoupon_UsesLatest()
    {
        _cart.AddItem("SKU-001", 1, 100.00m);
        _cart.ApplyCoupon("SAVE10"); // 10%
        _cart.ApplyCoupon("SAVE20"); // 20% replaces

        Assert.AreEqual(80.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_OnEmptyCart_TotalRemainsZero()
    {
        _cart.ApplyCoupon("HALF");

        Assert.AreEqual(0m, _cart.CalculateTotal());
    }
}

